  const part=parts[index],label='Text part '+(index+1),input=h('textarea',{'aria-label':label});input.value=part.text;
  const follow=node=>{for(const i of part.path)node=node?.childNodes[i];return node;};
  const original=element&&follow(element),staticText=original?.nodeType===3&&original.nodeValue===part.text;
  let configRef=null;
  if(!staticText){const found=[];for(const model of models.filter(x=>!x.file.endsWith('.json'))){for(const f of C.sourceFields(await W.source({file:model.file,script:model.script})))if(typeof f.value==='string'&&f.value===part.text)found.push({file:model.file,root:f.root,path:f.path,script:model.script});}if(found.length===1)configRef=found[0];}
  input.onchange=()=>safe(async()=>{if(configRef){await W.set(configRef,input.value,'Edit formatted text');return;}if(staticText){await W.enqueue(async()=>{const doc=new DOMParser().parseFromString(await W.text(W.root+page),'text/html'),node=follow(doc.querySelector(m.selector));if(node?.nodeType!==3)throw Error('The text structure changed. Select it again.');node.nodeValue=input.value;W.commit(new Map([[W.root+page,'<!doctype html>\n'+doc.documentElement.outerHTML]]),'Edit formatted text');});}else await PortfolioElements.save(W,page,m,'textNodes',JSON.stringify(part.path),input.value);});
