async function validateExport(){const issues=[];const ms=await W.models();for(const issue of W.analysis?.diagnostics||[])if(/\.(js|mjs|cjs|json)$/.test(issue.file))issues.push(short(issue.file)+': '+issue.message);for(const m of ms)if(m.error)issues.push(short(m.file)+': '+m.error);for(const m of ms)for(const r of m.roots){const inspect=(v,where)=>{if(v instanceof C.Raw)return;if(typeof v==='string'&&/^(\.\/)?assets\//.test(v)&&!W.paths().includes(W.root+v.replace(/^\.\//,'')))issues.push('Missing asset: '+v);if(Array.isArray(v)){const ids=v.filter(x=>x&&typeof x==='object'&&x.id).map(x=>x.id);if(new Set(ids).size<ids.length)issues.push('Duplicate item IDs in '+where);v.forEach((x,i)=>inspect(x,where+'['+i+']'));}else if(v&&typeof v==='object')for(const[k,x]of Object.entries(v))inspect(x,where+'.'+k);};inspect(r.value,r.name);}return [...new Set(issues)];}
async function exportZip(){await flushInputs();await PortfolioAdapters.syncIntro(W);const issues=await validateExport();if(issues.length&&!confirm('Review before export:\n\n'+issues.slice(0,8).join('\n')+(issues.length>8?'\n… and '+(issues.length-8)+' more.':'')+'\n\nExport anyway?'))return;busy('Preparing your website ZIP…','All original files are retained unless you explicitly deleted them.');try{const blob=await W.export(m=>$('#busy-detail').textContent='Packaging files · '+Math.round(m.percent)+'%');download(blob,W.name.replace(/-edited$/,'')+'-edited.zip');dirty=false;$('#save-status').textContent='Website ZIP exported';toast('Export ready. Upload these website files to your existing host.');}finally{done();}}
function download(blob,name){const u=URL.createObjectURL(blob),a=h('a',{href:u,download:name});document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);}
$('#export').onclick=()=>safe(exportZip);
